factorial.code:
begin
   integer procedure factorial(n); value n; integer n;
      factorial := if n <= 1 then 1 else n * factorial(n - 1);

   outinteger(1, factorial(10));
   outstring(1, "\n")
end

fizzbuzz.code:
begin
   integer i;

   boolean procedure divisible(n, d); value n, d; integer n, d;
      divisible := n % d * d = n;

   for i := 1 step 1 until 15 do
   begin
      if divisible(i, 15) then outstring(1, "FizzBuzz")
      else if divisible(i, 3) then outstring(1, "Fizz")
      else if divisible(i, 5) then outstring(1, "Buzz")
      else outinteger(1, i);
      outstring(1, "\n")
   end
end

higher-order.code:
begin
   integer array xs[1:10];
   integer i;

   boolean procedure even(x); value x; integer x;
      even := x % 2 * 2 = x;

   integer procedure square(x); value x; integer x;
      square := x * x;

   comment procedures can be passed as parameters (but not stored or returned);
   procedure filtermap(a, n, keep, f);
      value n; integer array a; integer n;
      boolean procedure keep; integer procedure f;
   begin
      integer i;
      for i := 1 step 1 until n do
         if keep(a[i]) then outinteger(1, f(a[i]))
   end;

   for i := 1 step 1 until 10 do xs[i] := i;
   filtermap(xs, 10, even, square);
   outstring(1, "\n")
end

shapes.code:
begin
   comment no records in ALGOL 60: a shape is a kind code plus two numbers;
   integer rectangle, triangle;

   integer procedure area(kind, a, b); value kind, a, b; integer kind, a, b;
      area := if kind = rectangle then a * b else a * b % 2;

   procedure show(kind, a, b); value kind, a, b; integer kind, a, b;
   begin
      if kind = rectangle then outstring(1, "Rectangle: ")
      else outstring(1, "Triangle: ");
      outinteger(1, area(kind, a, b));
      outstring(1, "\n")
   end;

   rectangle := 1;  triangle := 2;
   show(rectangle, 3, 4);
   show(triangle, 10, 3)
end

signature.code:
begin
   integer k;

   comment Jensen's device: i and term are called by name, so every use
      of term re-evaluates the caller's expression with the current i;
   integer procedure sum(i, lo, hi, term);
      value lo, hi; integer i, lo, hi, term;
   begin
      integer s;
      s := 0;
      for i := lo step 1 until hi do s := s + term;
      sum := s
   end;

   outinteger(1, sum(k, 1, 100, k));
   outinteger(1, sum(k, 1, 10, k * k));
   outinteger(1, sum(k, 1, 5, k * k * k));
   outstring(1, "\n")
end
